SET @zestbd_product_id = (SELECT id FROM products ORDER BY created_at, id LIMIT 1);
UPDATE products SET name = 'সবুজ পাতার ওয়াল ডেকর', headline = 'সবুজ পাতার ওয়াল ডেকর', description = 'সাদা নকশা করা ফ্রেমে সবুজ পাতা আর ছোট রঙিন ফুল। বসার ঘর, প্রবেশপথ বা আপনার পছন্দের দেয়ালে যোগ করুন সবুজের একটি সুন্দর ছোঁয়া।', media = '[{"id":"main","type":"image","label":"সামনে থেকে পণ্যের ছবি","src":"./assets/images/wall-decor-front.webp","fallback":"./assets/images/wall-decor-front.jpg","thumb":"./assets/images/thumb-wall-decor-front.webp","width":1200,"height":900,"alt":"সামনে থেকে সাদা নকশা করা ফ্রেমে সবুজ পাতা ও রঙিন ফুলের ওয়াল ডেকর"},{"id":"detail","type":"image","label":"ডান পাশ থেকে পণ্যের ছবি","src":"./assets/images/wall-decor-right.webp","fallback":"./assets/images/wall-decor-right.jpg","thumb":"./assets/images/thumb-wall-decor-right.webp","width":1200,"height":900,"alt":"ডান পাশ থেকে দেয়ালে সাজানো সবুজ পাতার ওয়াল ডেকর ও সাদা ফুলের নকশা"},{"id":"angle","type":"image","label":"বাম পাশ থেকে পণ্যের ছবি","src":"./assets/images/wall-decor-left.webp","fallback":"./assets/images/wall-decor-left.jpg","thumb":"./assets/images/thumb-wall-decor-left.webp","width":1200,"height":900,"alt":"বাম পাশ থেকে সাদা ফ্রেম ও সবুজ পাতার ওয়াল ডেকরের সম্পূর্ণ ছবি"},{"id":"close","type":"image","label":"ফ্রেম ও পাতার বিস্তারিত ছবি","src":"./assets/images/wall-decor-close.webp","fallback":"./assets/images/wall-decor-close.jpg","thumb":"./assets/images/thumb-wall-decor-close.webp","width":1200,"height":900,"alt":"কাছ থেকে ওয়াল ডেকরের সাদা ফ্রেম, ঘন সবুজ পাতা এবং ছোট রঙিন ফুল"}]', specifications = '{"পণ্যের ধরন":"দেয়াল সাজানোর ওয়াল ডেকর","নকশা":"ফুল ও লতাপাতার নকশা করা আয়তাকার ফ্রেম","রং":"সাদা ফ্রেম, সবুজ পাতা ও বিভিন্ন রঙের ছোট ফুল","মাপ ও উপাদান":"অর্ডারের আগে যোগাযোগ করে নিশ্চিত করুন","স্থাপনের তথ্য":"আপনার দেয়ালের সঙ্গে উপযোগিতা ও স্থাপনের পদ্ধতি আগে জেনে নিন"}', faq = '[{"question":"পণ্যের মাপ ও উপাদান কী?","answer":"মাপ ও উপাদানের নিশ্চিত তথ্য জানতে অর্ডারের আগে আমাদের সঙ্গে যোগাযোগ করুন।"},{"question":"ক্যাশ অন ডেলিভারি আছে?","answer":"হ্যাঁ, অর্ডার ফর্মে আপনার এলাকা নির্বাচন করে ক্যাশ অন ডেলিভারিতে অর্ডার দিতে পারবেন। পণ্য হাতে পেয়ে মূল্য পরিশোধ করবেন।"},{"question":"ডেলিভারি চার্জ কত?","answer":"ঢাকার ভেতরে বা বাইরে আপনার এলাকা নির্বাচন করলে ডেলিভারি চার্জ এবং মোট মূল্য অর্ডারের হিসাবে দেখা যাবে।"},{"question":"কত দিনে পণ্য পাব?","answer":"ডেলিভারি সময় আপনার এলাকা ও ডেলিভারি সেবার ওপর নির্ভর করে। নির্দিষ্ট সময় জানতে অর্ডারের আগে যোগাযোগ করুন।"},{"question":"পণ্য কীভাবে দেয়ালে লাগাতে হবে?","answer":"আপনার দেয়ালের ধরন ও পণ্যের জন্য উপযুক্ত স্থাপনের পদ্ধতি আমাদের কাছ থেকে জেনে নিন।"},{"question":"ফেরত বা বদলের নিয়ম কী?","answer":"অর্ডারের আগে ফেরত বা বদলের শর্ত নিশ্চিত করুন। ভুল বা ক্ষতিগ্রস্ত পণ্য পেলে অর্ডার নম্বর ও পণ্যের ছবি নিয়ে যোগাযোগ করুন।"}]', delivery_note = 'এলাকাভেদে ডেলিভারি চার্জ অর্ডারের হিসাবে দেখানো হবে।', version = version + 1 WHERE id = @zestbd_product_id;
INSERT IGNORE INTO site_settings (id, content) VALUES (1, '{"brandName":"zestbd","brandInitials":"ZB","tagline":"ঘর সাজুক আপনার মতো","mainSiteUrl":"https://zestbd.com/","supportPhone":"+8801XXXXXXXXX","supportEmail":"support@example.com","heroEyebrow":"ঘরের জন্য সবুজের ছোঁয়া","qualityTitle":"পণ্যের বিবরণ","qualityNote":"ছবি ও বিস্তারিত দেখে বেছে নিন","whyEyebrow":"কেন এই ওয়াল ডেকর?","whyTitle":"সাদামাটা দেয়ালে নতুন প্রাণ।","features":[{"title":"সবুজের ছোঁয়া","text":"সবুজ পাতা আর ছোট রঙিন ফুলে ঘরের দেয়ালে যোগ করুন প্রাণবন্ত একটি সাজ।"},{"title":"নকশা করা ফ্রেম","text":"সাদা ফ্রেমের ফুল ও লতাপাতার নকশা সবুজ পাতার সঙ্গে তৈরি করে সুন্দর বৈপরীত্য।"},{"title":"পছন্দের জায়গায়","text":"বসার ঘর, প্রবেশপথ বা কাজের জায়গার দেয়ালে মানানসই একটি স্থান বেছে নিন।"},{"title":"কাছ থেকে দেখুন","text":"সামনে ও দুই পাশ থেকে তোলা ছবিতে ফ্রেম, পাতা এবং ফুলের বিস্তারিত দেখুন।"}],"lifestyleEyebrow":"আপনার ঘরে zestbd","lifestyleTitle":"ঘরের একটি কোণ হোক একটু আলাদা।","lifestyleText":"সাদা ফ্রেম, সবুজ পাতা আর রঙিন ফুল। নিজের পছন্দের দেয়ালে সাজিয়ে নিন এই ওয়াল ডেকর।","lifestyleImage":"./assets/images/wall-decor-left.webp","lifestyleImageAlt":"ঘরের দেয়ালে সাদা নকশা করা ফ্রেমে সবুজ পাতা ও রঙিন ফুলের ওয়াল ডেকর","detailsTitle":"পণ্যটি সম্পর্কে জানুন।","detailsText":"মাপ, উপাদান বা স্থাপনের তথ্য জানতে অর্ডারের আগে আমাদের সঙ্গে যোগাযোগ করুন।","reviewsTitle":"ক্রেতাদের অভিজ্ঞতা","reviewsText":"যাঁরা পণ্যটি ঘরে সাজিয়েছেন, তাঁদের কথা।","reviews":[],"featuredTitle":"আরও পছন্দের পণ্য","featuredText":"zestbd-এর মূল দোকানে আরও পণ্য দেখুন।","featuredProducts":[],"orderTitle":"আপনার অর্ডার দিন","orderText":"নাম, মোবাইল নম্বর ও সম্পূর্ণ ঠিকানা লিখুন। পণ্য হাতে পেয়ে মূল্য পরিশোধ করুন।","faqTitle":"আপনার প্রশ্ন, আমাদের উত্তর","footerDescription":"ঘর সাজানোর ছোট ছোট পছন্দে আপনার পাশে zestbd।","policies":{"delivery":"ঢাকার ভেতরে ও বাইরে নির্বাচিত এলাকায় ডেলিভারি দেওয়া হয়। আপনার এলাকার ডেলিভারি চার্জ অর্ডারের হিসাবে দেখা যাবে। নির্দিষ্ট ডেলিভারি সময় জানতে অর্ডারের আগে যোগাযোগ করুন।","privacy":"অর্ডার প্রক্রিয়াকরণ ও ডেলিভারির জন্য আপনার নাম, মোবাইল নম্বর এবং ঠিকানা নেওয়া হয়। ডেলিভারি সম্পন্ন করতে প্রয়োজনীয় তথ্য সংশ্লিষ্ট ডেলিভারি সেবাকে দেওয়া হতে পারে। ব্যক্তিগত তথ্য সম্পর্কে প্রশ্ন থাকলে আমাদের সঙ্গে যোগাযোগ করুন।","returns":"অর্ডারের আগে ফেরত বা বদলের প্রযোজ্য শর্ত জেনে নিন। ভুল বা ক্ষতিগ্রস্ত পণ্য পেলে অর্ডার নম্বর এবং পণ্যের ছবি নিয়ে আমাদের সঙ্গে যোগাযোগ করুন।","terms":"অর্ডারের মোট মূল্যের মধ্যে পণ্যের দাম ও নির্বাচিত এলাকার ডেলিভারি চার্জ রয়েছে। ক্যাশ অন ডেলিভারিতে পণ্য হাতে পেয়ে মূল্য পরিশোধ করতে হবে। মাপ, উপাদান ও অন্যান্য বিস্তারিত অর্ডারের আগে নিশ্চিত করুন।"}}');
UPDATE site_settings SET content = JSON_MERGE_PATCH(content, '{"brandName":"zestbd","brandInitials":"ZB","tagline":"ঘর সাজুক আপনার মতো","heroEyebrow":"ঘরের জন্য সবুজের ছোঁয়া","qualityTitle":"পণ্যের বিবরণ","qualityNote":"ছবি ও বিস্তারিত দেখে বেছে নিন","whyEyebrow":"কেন এই ওয়াল ডেকর?","whyTitle":"সাদামাটা দেয়ালে নতুন প্রাণ।","features":[{"title":"সবুজের ছোঁয়া","text":"সবুজ পাতা আর ছোট রঙিন ফুলে ঘরের দেয়ালে যোগ করুন প্রাণবন্ত একটি সাজ।"},{"title":"নকশা করা ফ্রেম","text":"সাদা ফ্রেমের ফুল ও লতাপাতার নকশা সবুজ পাতার সঙ্গে তৈরি করে সুন্দর বৈপরীত্য।"},{"title":"পছন্দের জায়গায়","text":"বসার ঘর, প্রবেশপথ বা কাজের জায়গার দেয়ালে মানানসই একটি স্থান বেছে নিন।"},{"title":"কাছ থেকে দেখুন","text":"সামনে ও দুই পাশ থেকে তোলা ছবিতে ফ্রেম, পাতা এবং ফুলের বিস্তারিত দেখুন।"}],"lifestyleEyebrow":"আপনার ঘরে zestbd","lifestyleTitle":"ঘরের একটি কোণ হোক একটু আলাদা।","lifestyleText":"সাদা ফ্রেম, সবুজ পাতা আর রঙিন ফুল। নিজের পছন্দের দেয়ালে সাজিয়ে নিন এই ওয়াল ডেকর।","lifestyleImage":"./assets/images/wall-decor-left.webp","lifestyleImageAlt":"ঘরের দেয়ালে সাদা নকশা করা ফ্রেমে সবুজ পাতা ও রঙিন ফুলের ওয়াল ডেকর","detailsTitle":"পণ্যটি সম্পর্কে জানুন।","detailsText":"মাপ, উপাদান বা স্থাপনের তথ্য জানতে অর্ডারের আগে আমাদের সঙ্গে যোগাযোগ করুন।","reviewsTitle":"ক্রেতাদের অভিজ্ঞতা","orderTitle":"আপনার অর্ডার দিন","orderText":"নাম, মোবাইল নম্বর ও সম্পূর্ণ ঠিকানা লিখুন। পণ্য হাতে পেয়ে মূল্য পরিশোধ করুন।","faqTitle":"আপনার প্রশ্ন, আমাদের উত্তর","footerDescription":"ঘর সাজানোর ছোট ছোট পছন্দে আপনার পাশে zestbd।"}') WHERE id = 1;
UPDATE site_settings SET content = JSON_SET(content, '$.reviewsText', 'যাঁরা পণ্যটি ঘরে সাজিয়েছেন, তাঁদের কথা।') WHERE id = 1 AND COALESCE(JSON_LENGTH(JSON_EXTRACT(content, '$.reviews')), 0) = 0;
UPDATE site_settings SET content = JSON_SET(content, '$.policies.delivery', 'ঢাকার ভেতরে ও বাইরে নির্বাচিত এলাকায় ডেলিভারি দেওয়া হয়। আপনার এলাকার ডেলিভারি চার্জ অর্ডারের হিসাবে দেখা যাবে। নির্দিষ্ট ডেলিভারি সময় জানতে অর্ডারের আগে যোগাযোগ করুন।') WHERE id = 1 AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(content, '$.policies.delivery')), '') IN ('', 'null');
UPDATE site_settings SET content = JSON_SET(content, '$.policies.privacy', 'অর্ডার প্রক্রিয়াকরণ ও ডেলিভারির জন্য আপনার নাম, মোবাইল নম্বর এবং ঠিকানা নেওয়া হয়। ডেলিভারি সম্পন্ন করতে প্রয়োজনীয় তথ্য সংশ্লিষ্ট ডেলিভারি সেবাকে দেওয়া হতে পারে। ব্যক্তিগত তথ্য সম্পর্কে প্রশ্ন থাকলে আমাদের সঙ্গে যোগাযোগ করুন।') WHERE id = 1 AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(content, '$.policies.privacy')), '') IN ('', 'null');
UPDATE site_settings SET content = JSON_SET(content, '$.policies.returns', 'অর্ডারের আগে ফেরত বা বদলের প্রযোজ্য শর্ত জেনে নিন। ভুল বা ক্ষতিগ্রস্ত পণ্য পেলে অর্ডার নম্বর এবং পণ্যের ছবি নিয়ে আমাদের সঙ্গে যোগাযোগ করুন।') WHERE id = 1 AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(content, '$.policies.returns')), '') IN ('', 'null');
UPDATE site_settings SET content = JSON_SET(content, '$.policies.terms', 'অর্ডারের মোট মূল্যের মধ্যে পণ্যের দাম ও নির্বাচিত এলাকার ডেলিভারি চার্জ রয়েছে। ক্যাশ অন ডেলিভারিতে পণ্য হাতে পেয়ে মূল্য পরিশোধ করতে হবে। মাপ, উপাদান ও অন্যান্য বিস্তারিত অর্ডারের আগে নিশ্চিত করুন।') WHERE id = 1 AND COALESCE(JSON_UNQUOTE(JSON_EXTRACT(content, '$.policies.terms')), '') IN ('', 'null');
